package main

import (
	"bytes"
	"context"
	"os"
	"testing"

	system "github.com/rbln-sw/rblnlib-go/pkg/system/v1"
	resourceapi "k8s.io/api/resource/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
)

// Golden generated by unmodified checkpoint.go and types.go from pre-migration
// main e72abf06c0ac3027853df7a459258a9986371666, using unchanged Kubernetes/CDI dependencies.
func TestPreMigrationCheckpointReplay(t *testing.T) {
	data, err := os.ReadFile("testdata/pre-migration-checkpoint.json")
	if err != nil {
		t.Fatal(err)
	}
	cp := newCheckpoint()
	if err := cp.UnmarshalCheckpoint(data); err != nil {
		t.Fatal(err)
	}
	if err := cp.VerifyChecksum(); err != nil {
		t.Fatal(err)
	}
	out, err := cp.MarshalCheckpoint()
	if err != nil || !bytes.Equal(data, out) {
		t.Fatalf("checkpoint bytes changed: %s %v", out, err)
	}
	state := newTestState(t)
	if err := state.checkpointManager.CreateCheckpoint(DriverPluginCheckpointFile, cp); err != nil {
		t.Fatal(err)
	}
	state.rsdGroupFn = func(context.Context, []string) (string, error) {
		t.Fatal("replayed claim must not regroup hardware")
		return "", nil
	}
	state.resolveNodes = func(context.Context, string) ([]system.DeviceNode, error) {
		t.Fatal("replayed claim must not rebuild CDI device nodes")
		return nil, nil
	}
	devices, err := state.Prepare(t.Context(), &resourceapi.ResourceClaim{ObjectMeta: metav1.ObjectMeta{UID: "legacy-claim-uid"}})
	if err != nil || len(devices) != 1 || devices[0].DeviceName != "rbln1" || devices[0].PoolName != "worker-atom" || devices[0].CdiDeviceIds[0] != "k8s.rebellions.ai/npu=legacy-claim-uid-rbln1" {
		t.Fatalf("legacy allocation changed: %+v %v", devices, err)
	}
}
